(function () {
  function getScholarBaseUrl() {
    var useCdn = String("{{ site.google_scholar_stats_use_cdn | default: true }}") === "true";
    var repo = "{{ site.repository | default: '' }}";
    if (!repo) return null;
    // Data is generated by GitHub Actions into the `google-scholar-stats` branch.
    if (useCdn) return "https://cdn.jsdelivr.net/gh/" + repo + "@google-scholar-stats/";
    return "https://raw.githubusercontent.com/" + repo + "/google-scholar-stats/";
  }

  function safeText(el, text) {
    if (!el) return;
    el.textContent = text;
  }

  async function updateScholarStats() {
    var base = getScholarBaseUrl();
    if (!base) return;

    var url = base + "gs_data.json";
    var resp;
    try {
      resp = await fetch(url, { cache: "no-cache" });
    } catch (e) {
      return;
    }
    if (!resp.ok) return;

    var data;
    try {
      data = await resp.json();
    } catch (e) {
      return;
    }

    if (data && typeof data.citedby !== "undefined") {
      safeText(document.getElementById("total_cit"), String(data.citedby));
    }

    var citationEles = document.getElementsByClassName("show_paper_citations");
    if (!citationEles || !citationEles.length) return;

    Array.prototype.forEach.call(citationEles, function (element) {
      var paperId = element.getAttribute("data");
      if (!paperId) return;
      var pubs = data && data.publications;
      var pub = pubs && pubs[paperId];
      var num = pub && pub.num_citations;
      if (typeof num === "undefined" || num === null) return;
      element.textContent = "| Citations: " + String(num);
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      updateScholarStats();
      initNavHighlight();
    });
  } else {
    updateScholarStats();
    initNavHighlight();
  }

  function initNavHighlight() {
    var links = document.querySelectorAll(".topnav__link");
    if (!links.length) return;

    var sectionIds = ["about-me", "research", "publications", "service", "contact"];
    var sections = sectionIds
      .map(function (id) { return document.getElementById(id); })
      .filter(Boolean);

    function setActive(id) {
      Array.prototype.forEach.call(links, function (link) {
        var href = link.getAttribute("href") || "";
        var hash = href.indexOf("#") >= 0 ? href.slice(href.indexOf("#") + 1) : "";
        link.classList.toggle("is-active", hash === id);
      });
    }

    function onScroll() {
      var scrollPos = window.scrollY + 100;
      var current = sectionIds[0];
      sections.forEach(function (section) {
        if (section.offsetTop <= scrollPos) current = section.id;
      });
      setActive(current);
    }

    Array.prototype.forEach.call(links, function (link) {
      link.addEventListener("click", function () {
        var href = link.getAttribute("href") || "";
        var hash = href.indexOf("#") >= 0 ? href.slice(href.indexOf("#") + 1) : "";
        if (hash) setActive(hash);
      });
    });

    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
  }
})();


